// Pure helpers behind the factory-band mod: no `$`, no I/O of their own, so
// `node --test` covers them without the engine. The integrated check takes
// its git runner as an argument. register.tsx is the only caller.

/** What the band shows for a field no source recorded. */
export const UNKNOWN = '-'

/** How long each probe (git per worker, each events query) may take. */
export const PROBE_BUDGET_MS = 400

/** The shortest gap between the starts of two refreshes. */
export const REFRESH_GAP_MS = 5_000

/** The local events service's query route. */
export const EVENTS_URL = 'http://localhost:7430/api/events'

/** The events source belt records lifecycle entries under. */
export const LEDGER_SOURCE = 'belt-ledger'

/** The events source items addressed to a session arrive under. */
export const INBOX_SOURCE = 'belt-inbox'

/** The ref the ahead count compares against when origin names no HEAD. */
export const DEFAULT_BRANCH = 'main'

// One page per query is plenty for one run: a factory of a few workers
// leaves tens of ledger entries, not hundreds.
const LEDGER_LIMIT = 200
const INBOX_LIMIT = 100

// The agent definitions the factory spawns its workers from, optionally
// under a plugin's `<plugin>:` prefix.
const WORKER_TYPE = /(?:^|:)factory-worker-(low|medium|high)$/

// The eight header lines of a factory message, in contract order.
const HEADER_KEYS = ['kind', 'unit', 'worktree', 'branch', 'model', 'effort', 'reply_to', 'needs_reply'] as const

// A header line, `key: value`; the value runs to the end of the line.
const HEADER_LINE = /^([a-z_]+):[ \t]*(.*?)[ \t]*$/

// The `kind:` line of a message a worker sends, anywhere in the text: an
// answer handed back to its spawner can be led by the engine's warning, and
// a worker may quote its task above its own header.
const KIND_LINE = /^kind:[ \t]*(status|question|ready|blocked)[ \t]*$/gm

// Kinds after which the worker waits for the orchestrator.
const NEEDS_ANSWER = new Set(['blocked', 'question'])

// Agent statuses of a loop at work or about to be.
const LIVE = new Set(['pending', 'running', 'waiting'])

// Every belt denial reason carries `belt[<guard>]: `, possibly behind the
// engine's own prefix on the same line.
const BELT_REASON = /belt\[[^\]]+\]:/

// What git says when `-C` names a worktree that is gone: a removed
// directory, or one that no longer holds a repository.
const WORKTREE_GONE = /cannot change to|not a git repository/

// States after which a worker whose loop ended has nothing left to show.
const DONE = new Set(['integrated', 'removed'])

/**
 * The default branch's tree and full ref name in one call; the `^{tree}`
 * comes first because `--symbolic-full-name` applies to what follows it.
 */
export const DEFAULT_BRANCH_ARGS = ['rev-parse', 'origin/HEAD^{tree}', '--symbolic-full-name', 'origin/HEAD'] as const

/** Uncommitted changes in the worktree. */
export const STATUS_ARGS = ['status', '--porcelain'] as const

/** Every git call runs untranslated, so WORKTREE_GONE reads git's own words on any locale. */
export const GIT_ENV = { LC_ALL: 'C' } as const

/** How many commits HEAD has that `ref` lacks. */
export function aheadArgs(ref: string): string[] {
  return ['rev-list', '--count', `${ref}..HEAD`]
}

/** The tree a merge of HEAD into `ref` would write, conflicts or not; needs git 2.38. */
export function mergeTreeArgs(ref: string): string[] {
  return ['merge-tree', '--write-tree', ref, 'HEAD']
}

/** The most first-parent commits the integrated walk merges; a longer range reads as unknown. */
export const WALK_LIMIT = 200

/** Where HEAD forked from `ref`; the walk starts after it. */
export function mergeBaseArgs(ref: string): string[] {
  return ['merge-base', ref, 'HEAD']
}

/**
 * The first-parent commits of `ref` since `base`, newest first, one
 * `<commit> <tree>` line each on any git (`rev-list --format` needs
 * `--no-commit-header`, git 2.33). It asks for one more than WALK_LIMIT, so
 * a range that is too long shows as one. `--no-show-signature` keeps a
 * `log.showSignature` config from printing gpg lines between them.
 */
export function walkArgs(base: string, ref: string): string[] {
  return ['log', '--no-show-signature', '--first-parent', `--max-count=${WALK_LIMIT + 1}`, '--format=%H %T', `${base}..${ref}`]
}

/** A merge of HEAD into each commit named on stdin, all in one call; needs git 2.40. */
export const WALK_MERGE_ARGS = ['merge-tree', '--write-tree', '--stdin', '--name-only', '--no-messages'] as const

export type Header = Record<(typeof HEADER_KEYS)[number], string>

/** One factory worker as its spawn recorded it. */
export type Worker = {
  agentId: string
  name: string
  /** The claimed worktree, absolute; null when neither the spawn nor the task named one. */
  worktree: string | null
  /** What the spawn result said the worker runs on. */
  model: string | null
  /** The kind of the last contract message the worker sent. */
  lastKind: string | null
}

/** One agent of this session, as `$.agent.list()` returns it. */
export type AgentLike = { id: string; status: string }

export type Liveness = 'live' | 'idle' | 'gone' | 'unknown'

/**
 * What git says about a worker's worktree. `isIntegrated`: merging HEAD
 * into the default branch would change nothing, as after a squash merge;
 * null when git could not say or was not asked: a walk past its limit, a
 * check that ran out of time, or a loop not yet at rest.
 */
export type GitFacts = { isDirty: boolean; ahead: number; isIntegrated: boolean | null }

/** One git call's result, as `$.process.run` resolves it. */
export type GitRun = { exitCode: number; stdout: string; stderr: string; isStdoutTruncated?: boolean }

/** One git call in a worker's worktree, with stdin when given: its result, or null when git never answered. */
export type GitRunner = (args: readonly string[], stdin?: string) => Promise<GitRun | null>

/** A first-parent commit of the default branch and its tree. */
export type MainCommit = { commit: string; tree: string }

/** One merge in merge-tree's `--stdin` output. */
export type WalkMerge = { isClean: boolean; tree: string }

/** What git said about a worktree: its facts, `removed` once it is gone, null when git could not say. */
export type WorktreeRead = GitFacts | 'removed' | null

/** The default branch as `origin/HEAD` names it, and its tree when known. */
export type DefaultBranch = { ref: string; tree: string | null }

/** What belt's ledger recorded when a worker started. */
export type LedgerFacts = { model: string | null; effort: string | null }

/** The ledger read for one run: start facts per agent id and the workers' denials. */
export type LedgerRead = { facts: Map<string, LedgerFacts>; denies: number | null }

/** What one refresh read for one worker. */
export type WorkerFacts = { state: string; model: string | null; effort: string | null }

/** What one refresh read for the run; null counts are sources that did not answer. */
export type Probe = { facts: Record<string, WorkerFacts>; ledgerDenies: number | null; inbox: number | null }

/** What the band draws. */
export type BandView = { summary: string; rows: string[]; isAnyReady: boolean }

/**
 * One factory run, kept in one atom so that a spawn and the refresh that
 * closes the run cannot interleave. `workerIds` keeps every worker the run
 * spawned, dropped ones included, so their denials keep counting.
 */
export type Run = {
  workers: Worker[]
  startedAt: number | null
  workerIds: string[]
  guardDenies: number
  probe: Probe | null
}

/** No run: no workers, no counts. */
export const NO_RUN: Run = { workers: [], startedAt: null, workerIds: [], guardDenies: 0, probe: null }

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function textOf(value: unknown): string | null {
  return typeof value === 'string' && value !== '' ? value : null
}

// The events service's answer as an array, or null when it is not one.
function parseArray(body: string | null): unknown[] | null {
  if (body === null) return null
  try {
    const parsed: unknown = JSON.parse(body)
    return Array.isArray(parsed) ? parsed : null
  } catch {
    return null
  }
}

/** True for an agent type the factory spawns its workers from. */
export function isWorkerType(type: string): boolean {
  return WORKER_TYPE.test(type)
}

/** The eight contract header lines at the top of a message, or null when any is missing or out of order. */
export function parseHeader(text: string): Header | null {
  const lines = text.trimStart().split(/\r?\n/)
  if (lines.length < HEADER_KEYS.length) return null
  const header: Partial<Header> = {}
  for (const [i, key] of HEADER_KEYS.entries()) {
    const match = HEADER_LINE.exec(lines[i] ?? '')
    if (match === null || match[1] !== key || match[2] === '') return null
    header[key] = match[2]
  }
  return header as Header
}

/** True for a spawn prompt that opens with a `task` header. */
export function isTaskMessage(prompt: string): boolean {
  return parseHeader(prompt)?.kind === 'task'
}

/** The convenience guard's deny reason. */
export function guardReason(type: string): string {
  return `factory-band: the ${type} prompt lacks the eight-line task header (kind, unit, worktree, branch, model, effort, reply_to, needs_reply); see the factory skill's contract.md`
}

/** The last worker kind (status, question, ready, blocked) a text names, or null when it names none. */
export function kindOf(text: string): string | null {
  return [...text.matchAll(KIND_LINE)].at(-1)?.[1] ?? null
}

/** `~/x` under `home`; an absolute path as given; null for a relative path or an unknown home. */
export function expandHome(path: string, home: string | null): string | null {
  if (path === '~' || path.startsWith('~/')) return home === null ? null : `${home}${path.slice(1)}`
  return path.startsWith('/') ? path : null
}

/** The worker a spawn started: the worktree from the spawn's cwd, else the task header. */
export function workerFrom(input: {
  agentId: string
  name?: string
  cwd?: string
  prompt: string
  model: string
  home: string | null
}): Worker {
  const header = parseHeader(input.prompt)
  const named = input.cwd ?? header?.worktree
  return {
    agentId: input.agentId,
    name: input.name ?? header?.unit ?? input.agentId,
    worktree: named === undefined ? null : expandHome(named, input.home),
    model: textOf(input.model),
    lastKind: null,
  }
}

/** The list with `worker` in its place, replacing an earlier record of the same agent. */
export function upsertWorker(list: readonly Worker[], worker: Worker): Worker[] {
  return [...list.filter(known => known.agentId !== worker.agentId), worker]
}

/** The list with the agent's last message kind set; unchanged when the agent is no worker. */
export function withKind(list: readonly Worker[], agentId: string, kind: string): Worker[] {
  return list.map(worker => (worker.agentId === agentId ? { ...worker, lastKind: kind } : worker))
}

/** An events id at `ms`: ids are unix nanoseconds, zero-padded to 20 digits, so they sort by time. */
export function idAt(ms: number): string {
  return `${Math.max(0, Math.floor(ms))}000000`.padStart(20, '0')
}

/** The query for one source's entries that mention this session. */
export function eventsUrl(source: string, sessionId: string): string {
  const limit = source === LEDGER_SOURCE ? LEDGER_LIMIT : INBOX_LIMIT
  return `${EVENTS_URL}?source=${encodeURIComponent(source)}&q=${encodeURIComponent(sessionId)}&limit=${limit}`
}

type Entry = { id: string; tags: Record<string, unknown> }

function entriesOf(body: string | null): Entry[] | null {
  const items = parseArray(body)
  if (items === null) return null
  const entries: Entry[] = []
  for (const item of items) {
    const id = isRecord(item) ? textOf(item.id) : null
    if (id !== null && isRecord(item) && isRecord(item.tags)) entries.push({ id, tags: item.tags })
  }
  return entries
}

/**
 * belt's ledger as one run sees it: the newest subagent-start facts per
 * agent id, and the auto-mode denials recorded for this session's worker
 * agents. The answer comes newest first; denies is null when the answer is
 * not an event array.
 */
export function parseLedger(body: string | null, scope: { sessionId: string; workerIds: ReadonlySet<string> }): LedgerRead {
  const facts = new Map<string, LedgerFacts>()
  const entries = entriesOf(body)
  if (entries === null) return { facts, denies: null }
  let denies = 0
  for (const { tags } of entries) {
    const agentId = textOf(tags.agent_id)
    if (agentId === null) continue
    if (tags.event === 'subagent-start' && !facts.has(agentId)) {
      facts.set(agentId, { model: textOf(tags.model), effort: textOf(tags.effort) })
    }
    if (tags.event === 'permission-denied' && tags.session_id === scope.sessionId && scope.workerIds.has(agentId)) denies += 1
  }
  return { facts, denies }
}

/** How many belt-inbox items are addressed to this session since the run started; null when the answer is not an event array. */
export function countInbox(body: string | null, scope: { sessionId: string; sinceId: string }): number | null {
  const entries = entriesOf(body)
  if (entries === null) return null
  return entries.filter(({ id, tags }) => tags.to === scope.sessionId && id >= scope.sinceId).length
}

/**
 * The default branch from DEFAULT_BRANCH_ARGS' output (the tree, then
 * `refs/remotes/origin/main`): `origin/main` and its tree; `main` and no
 * tree when origin names no HEAD.
 */
export function parseDefaultBranch(stdout: string | null): DefaultBranch {
  const [tree = '', name = ''] = stdout?.trim().split('\n') ?? []
  const ref = name.replace(/^refs\/remotes\//, '')
  if (ref === '' || ref === name || tree === '') return { ref: DEFAULT_BRANCH, tree: null }
  return { ref, tree }
}

/** A git call's stdout, or null when it exited non-zero or never answered. */
export function stdoutOf(run: GitRun | null): string | null {
  return run !== null && run.exitCode === 0 ? run.stdout : null
}

/**
 * True when git refused because the worktree is gone: exit 128 and git
 * saying so. A timeout rejects the call and a signal reads as exit 1, so
 * neither reads as gone.
 */
export function isWorktreeGone(run: GitRun | null): boolean {
  return run !== null && run.exitCode === 128 && WORKTREE_GONE.test(run.stderr)
}

/** The worktree's facts from `git status --porcelain` and `git rev-list --count`, or null when either failed. */
export function gitFactsFrom(status: string | null, count: string | null): GitFacts | null {
  const ahead = Number.parseInt(count?.trim() ?? '', 10)
  if (status === null || Number.isNaN(ahead)) return null
  return { isDirty: status.trim() !== '', ahead, isIntegrated: false }
}

/** True when a worker's tree is worth the merge-tree check: clean, ahead, and the worker sent ready. */
export function isReadyCandidate(git: GitFacts | null, lastKind: string | null): boolean {
  return git !== null && !git.isDirty && git.ahead > 0 && lastKind === 'ready'
}

/**
 * True when an agent's loop waits idle or has ended, the only loops whose
 * ready tree gets the merge-tree check: a live loop reads in flight and an
 * unknown one reads unknown, whatever the check would find.
 */
export function isLoopAtRest(liveness: Liveness): boolean {
  return liveness === 'idle' || liveness === 'gone'
}

/**
 * True when the tree a merge of HEAD into the default branch would write
 * is the default branch's own tree: the branch's changes are already there.
 * False when either is unknown (git before 2.38, a conflict, no origin HEAD).
 */
export function isIntegratedTree(mergeTreeOut: string | null, defaultTree: string | null): boolean {
  const merged = mergeTreeOut?.trim().split('\n')[0] ?? ''
  return merged !== '' && defaultTree !== null && merged === defaultTree.trim()
}

/** True when `git merge-base` found no fork point: the histories share nothing, so there is nothing to walk. */
export function isUnrelated(run: GitRun | null): boolean {
  return run !== null && run.exitCode === 1 && run.stdout.trim() === ''
}

/** The walk's commits from walkArgs' output, newest first; null when git could not say or the range runs past WALK_LIMIT. */
export function parseWalk(stdout: string | null): MainCommit[] | null {
  const lines = stdout?.split('\n').filter(line => line.trim() !== '') ?? null
  if (lines === null || lines.length > WALK_LIMIT) return null
  const fields = lines.map(line => line.trim().split(' '))
  if (fields.some(pair => pair.length !== 2)) return null
  return fields.map(([commit = '', tree = '']) => ({ commit, tree }))
}

/** merge-tree's stdin for the walk: one `<commit> HEAD` line per commit. */
export function walkInput(commits: readonly MainCommit[]): string {
  return commits.map(({ commit }) => `${commit} HEAD\n`).join('')
}

/**
 * The merges in WALK_MERGE_ARGS' output, in input order, or null when it
 * does not parse. Fields are NUL-separated. Each merge is its status (1
 * clean, 0 conflicted), its tree, the conflicted file names, and an empty
 * field that closes it.
 */
export function parseMerges(stdout: string): WalkMerge[] | null {
  const fields = stdout.split('\0')
  const merges: WalkMerge[] = []
  let i = 0
  while (i < fields.length - 1) {
    const [status, tree = ''] = [fields[i], fields[i + 1]]
    if ((status !== '0' && status !== '1') || tree === '') return null
    i += 2
    while (i < fields.length && fields[i] !== '') i += 1
    merges.push({ isClean: status === '1', tree })
    i += 1
  }
  return merges
}

/**
 * True when HEAD landed in one of the commits: a clean merge into that
 * commit writes the commit's own tree. False when merge-tree refused, as a
 * git before 2.40 does without `--stdin`: no proof. Null when git never
 * answered or its output does not line up with the commits.
 */
export function landedIn(commits: readonly MainCommit[], run: GitRun | null): boolean | null {
  if (run === null || run.isStdoutTruncated === true) return null
  if (run.exitCode !== 0) return false
  const merges = parseMerges(run.stdout)
  if (merges === null || merges.length !== commits.length) return null
  return merges.some((merge, i) => merge.isClean && merge.tree === commits[i]?.tree)
}

// A git call's whole stdout: exit 0 and nothing cut off, else null.
function fullStdoutOf(run: GitRun | null): string | null {
  return run?.isStdoutTruncated === true ? null : stdoutOf(run)
}

/**
 * Whether the default branch already holds HEAD's changes: the integrated
 * check in the loom skill's loom.md. The tip merge comes first. When it
 * proves nothing (a conflict, or a tree that differs because the default
 * branch changed or reverted those lines since the squash), the same check
 * runs against each first-parent commit since the fork point, at most
 * WALK_LIMIT of them. Null when git could not say, so the worker reads
 * unknown and stays on the band rather than reading integrated.
 */
export async function integratedOf(runGit: GitRunner, branch: DefaultBranch): Promise<boolean | null> {
  const tip = await runGit(mergeTreeArgs(branch.ref))
  if (tip === null) return null
  if (isIntegratedTree(stdoutOf(tip), branch.tree)) return true
  const base = await runGit(mergeBaseArgs(branch.ref))
  if (isUnrelated(base)) return false
  const forkPoint = stdoutOf(base)?.trim() ?? ''
  if (forkPoint === '') return null
  const commits = parseWalk(fullStdoutOf(await runGit(walkArgs(forkPoint, branch.ref))))
  if (commits === null) return null
  if (commits.length === 0) return false
  return landedIn(commits, await runGit(WALK_MERGE_ARGS, walkInput(commits)))
}

/** Where an agent's loop stands for the band; `gone` once it ended or left the list. */
export function livenessOf(agents: readonly AgentLike[] | null, agentId: string): Liveness {
  if (agents === null) return 'unknown'
  const status = agents.find(agent => agent.id === agentId)?.status
  if (status !== undefined && LIVE.has(status)) return 'live'
  return status === 'idle' ? 'idle' : 'gone'
}

/**
 * A worker's state. A loop at work is in flight. A clean tree whose worker
 * sent ready is ready, or integrated once the default branch holds its
 * changes, or unknown while git cannot say which; a dirty tree after a
 * ready is in flight again. A worker whose
 * last message waits for an answer is blocked. An idle worker is in
 * flight; one whose loop ended without a ready is stopped. A worktree
 * that is gone is removed, as loom leaves it after landing or dropping the
 * unit. Abandoned is the weaver's call after a survey, never the band's.
 */
export function workerState(input: { git: WorktreeRead; liveness: Liveness; lastKind: string | null }): string {
  const { git, liveness, lastKind } = input
  if (git === 'removed') return 'removed'
  if (git === null || liveness === 'unknown') return UNKNOWN
  if (liveness === 'live') return 'in flight'
  if (lastKind === 'ready') {
    if (git.isDirty) return 'in flight'
    if (git.ahead === 0 || git.isIntegrated === true) return 'integrated'
    return git.isIntegrated === null ? UNKNOWN : 'ready'
  }
  if (lastKind !== null && NEEDS_ANSWER.has(lastKind)) return 'blocked'
  return liveness === 'idle' ? 'in flight' : 'stopped'
}

/** One refresh's reading of every worker and of the run's counts. */
export function probeFrom(input: {
  workers: readonly Worker[]
  agents: readonly AgentLike[] | null
  gits: readonly WorktreeRead[]
  ledger: LedgerRead
  inbox: number | null
}): Probe {
  const facts: Record<string, WorkerFacts> = {}
  input.workers.forEach((worker, i) => {
    const recorded = input.ledger.facts.get(worker.agentId)
    const liveness = livenessOf(input.agents, worker.agentId)
    facts[worker.agentId] = {
      state: workerState({ git: input.gits[i] ?? null, liveness, lastKind: worker.lastKind }),
      model: recorded?.model ?? null,
      effort: recorded?.effort ?? null,
    }
  })
  return { facts, ledgerDenies: input.ledger.denies, inbox: input.inbox }
}

/**
 * The workers a refresh may drop: integrated or with their worktree
 * removed, and their loop ended, so rows and git probes do not pile up.
 */
export function prunableIds(workers: readonly Worker[], probe: Probe, agents: readonly AgentLike[] | null): Set<string> {
  const ids = workers
    .map(worker => worker.agentId)
    .filter(id => DONE.has(probe.facts[id]?.state ?? UNKNOWN) && livenessOf(agents, id) === 'gone')
  return new Set(ids)
}

/** The run with `worker` recorded; the first worker starts the run at `now`. */
export function withWorker(run: Run, worker: Worker, now: number): Run {
  const isKnown = run.workerIds.includes(worker.agentId)
  return {
    ...run,
    workers: upsertWorker(run.workers, worker),
    startedAt: run.startedAt ?? now,
    workerIds: isKnown ? run.workerIds : [...run.workerIds, worker.agentId],
  }
}

/** The run with one more guard denial when `agentId` is one of its workers. */
export function withGuardDeny(run: Run, agentId: string): Run {
  return run.workerIds.includes(agentId) ? { ...run, guardDenies: run.guardDenies + 1 } : run
}

/**
 * The run after a refresh: the probe stored and the workers it found done
 * dropped. Dropping the last worker closes the run, so the next spawn
 * starts with fresh counts. A worker spawned while the refresh ran is not
 * in the probe, so it stays and keeps the run open.
 */
export function settleRun(run: Run, probe: Probe, agents: readonly AgentLike[] | null): Run {
  const done = prunableIds(run.workers, probe, agents)
  const workers = run.workers.filter(worker => !done.has(worker.agentId))
  return workers.length === 0 ? NO_RUN : { ...run, workers, probe }
}

/**
 * True when a tool call's result is a belt denial. A denial from a settings
 * hook reaches a plugin as an errored result whose text is the reason, so
 * only the first line counts: a failed command whose output mentions belt
 * does not.
 */
export function isBeltRefusal(result: unknown): boolean {
  if (!isRecord(result)) return false
  if (typeof result.deny === 'string') return BELT_REASON.test(result.deny)
  if (result.isError !== true || typeof result.text !== 'string') return false
  return BELT_REASON.test(result.text.trimStart().split('\n')[0] ?? '')
}

/** True when no refresh started in the last `REFRESH_GAP_MS`. */
export function isRefreshDue(now: number, lastRefreshAt: number | null): boolean {
  return lastRefreshAt === null || now - lastRefreshAt >= REFRESH_GAP_MS
}

/** How long until the gap since the last refresh has passed: 0 when it already has. */
export function trailingDelay(now: number, lastRefreshAt: number | null): number {
  return lastRefreshAt === null ? 0 : Math.max(0, lastRefreshAt + REFRESH_GAP_MS - now)
}

type Row = [name: string, state: string, model: string, effort: string]

function rowOf(worker: Worker, facts: WorkerFacts | undefined): Row {
  return [worker.name, facts?.state ?? UNKNOWN, worker.model ?? facts?.model ?? UNKNOWN, facts?.effort ?? UNKNOWN]
}

// Each row's columns padded to the widest cell, two spaces between them.
function alignRows(rows: readonly Row[]): string[] {
  const width = (col: 0 | 1 | 2): number => Math.max(...rows.map(row => row[col].length))
  const [name, state, model] = [width(0), width(1), width(2)]
  return rows.map(row => [row[0].padEnd(name), row[1].padEnd(state), row[2].padEnd(model), row[3]].join('  '))
}

/**
 * The band: a summary line, then one aligned row per worker as name,
 * state, model and effort. The model comes from the spawn, then the
 * ledger; effort from the ledger alone. Denies add the workers' belt guard
 * denials to the ledger's; inbox is a dash while belt-inbox has not answered.
 */
export function bandView(input: { workers: readonly Worker[]; probe: Probe | null; guardDenies: number }): BandView {
  const rows = input.workers.map(worker => rowOf(worker, input.probe?.facts[worker.agentId]))
  const denies = input.guardDenies + (input.probe?.ledgerDenies ?? 0)
  const inbox = input.probe?.inbox ?? null
  const noun = rows.length === 1 ? 'worker' : 'workers'
  return {
    summary: `factory · ${rows.length} ${noun} · denies ${denies} · inbox ${inbox ?? UNKNOWN}`,
    rows: alignRows(rows),
    isAnyReady: rows.some(row => row[1] === 'ready'),
  }
}

